BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"g":4,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"listening","skill":"الاستماع والتحقق من التفاصيل","passage":"يقرأ المعلم: «اتفقت مجموعة على ترتيب حديقة المدرسة. تولت نورة جمع الأدوات، وراجع حامد قائمة المهام، ثم بدأ الجميع العمل». يحدد المستمع الأدوار وتسلسل الأحداث، ولا يضيف شخصيات غير مذكورة. لا توجد ملفات صوتية مولدة مع هذه المادة؛ يلزم أداء المعلم.","q1":"من راجع قائمة المهام؟","a1":"حامد","w1":["نورة","أمين المكتبة","المدير"],"q2":"ما المهمة التي تولتها نورة؟","a2":"جمع الأدوات","w2":["شراء الكتب","كتابة رسالة","وضع علامات الامتحان"],"practice":"استمع للموقف ثم اكتب مخطط أدوار الفريق وحدثين متتابعين. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"القراءة والفكرة والدليل","passage":"«خصصت المدرسة ركنًا لتبادل الكتب. يضع الطلاب الكتب التي انتهوا منها ويستعيرون أخرى. ويسجل المسؤول عملية الإعارة للحفاظ على النظام». الفكرة الأساسية تنظيم تبادل الكتب، والتفاصيل تبين آلية ذلك. لا يدعي النص نتائج كمية أو أعدادًا غير مذكورة.","q1":"ما الهدف من ركن تبادل الكتب؟","a1":"تنظيم استعارة الكتب بين الطلاب","w1":["إلغاء القراءة","بيع الأجهزة","استبدال جميع الحصص"],"q2":"ما دور المسؤول حسب النص؟","a2":"تسجيل الإعارة","w2":["إغلاق الركن نهائيًا","اختيار كتب عشوائيًا","تحديد درجات الطلاب"],"practice":"حدد الفكرة الرئيسة وتفصيلين داعمين في فقرة شبيهة من كتابتك. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي: المعرفة والنكرة","passage":"«كتابٌ» نكرة لأنه لا يحدد كتابًا معينًا، و«الكتابُ» معرفة بأل؛ وتتعدد المعارف مثل العلم والضمير والاسم الموصول. لا يكفي وجود أي ألف ولام داخل الكلمة للحكم؛ نلاحظ دخول أل التعريف إلى الاسم.","q1":"أي كلمة معرفة بأل؟","a1":"الكتاب","w1":["كتاب","قلم","دفتر"],"q2":"أي كلمة نكرة؟","a2":"دفتر","w2":["الدفتر","محمد","هذا"],"practice":"صنف ثمانية أسماء إلى معارف ونكرات ثم اكتب جملتين صحيحتين. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية: مبتدأ وخبر","passage":"«المكتبةُ مرتبةٌ» جملة اسمية؛ «المكتبةُ» مبتدأ مرفوع و«مرتبةٌ» خبر مرفوع، يكتمل به المعنى. قد يكون الخبر جملة أو شبه جملة في أمثلة أخرى، ولذلك نقرأ تركيب الجملة بدل الإعراب بالاعتماد على كلمة واحدة.","q1":"ما المبتدأ في «المكتبة مرتبة»؟","a1":"المكتبة","w1":["مرتبة","في","كتاب"],"q2":"ما الخبر في المثال؟","a2":"مرتبة","w2":["المكتبة","قرأ","على"],"practice":"كوّن أربع جمل اسمية مع مبتدأ وخبر وعلّل اكتمال المعنى. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي: الأمر والنهي","passage":"«رتّبْ أوراقَك» أمر يدعو إلى أداء فعل، و«لا تُهملْ واجبَك» نهي تدل عليه «لا» الناهية مع المضارع. يتغير أثر الطلب بحسب نبرة الخطاب ومقامه؛ يمكن تحويل الأمر إلى صياغة مهذبة دون تغيير الهدف.","q1":"أي عبارة تتضمن نهيًا؟","a1":"لا تهمل واجبك","w1":["رتب أوراقك","أنجز الطالب المهمة","الكتاب مفيد"],"q2":"أي صيغة أمر؟","a2":"رتّبْ","w2":["يرتّب","ترتيب","الترتيب"],"practice":"اكتب أمرين ونهيين في سياقات آمنة ثم حولهما إلى عبارات مهذبة. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية: همزة القطع والوصل","passage":"«أحمد» اسم يبدأ بهمزة قطع تنطق في البدء والوصل، و«استمع» فعل ماض سداسي يبدأ بهمزة وصل. تصحح الهمزة عند التحقق من بنية الكلمة، لا بإضافة رأس همزة إلى كل ألف في أول كلمة.","q1":"أي كلمة فيها همزة وصل؟","a1":"استمع","w1":["أخذ","أحمد","إجابة"],"q2":"أي كلمة فيها همزة قطع؟","a2":"إجابة","w2":["اكتب","استمع","انطلق"],"practice":"اجمع ثماني كلمات تبدأ بألف وصنف همزاتها مع توضيح سبب الرسم. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي والفقرة المنظمة","passage":"تحتاج الفقرة إلى خط مقروء وتباعد متزن بين السطور والكلمات، مع نقطة عند اكتمال الجملة وعلامة استفهام للسؤال. مثال مستقل: «قرأت مريم القصة. لماذا أعجبتها؟ لأنها تعلمت منها قيمة التعاون». نميز بين السؤال والجواب في الرسم.","q1":"أين توضع علامة الاستفهام؟","a1":"بعد السؤال","w1":["قبل كل كلمة","بدل جميع النقاط","داخل الحرف"],"q2":"ما الذي يسهل قراءة الفقرة؟","a2":"وضوح الخط والمسافات والعلامات","w2":["وصل جميع الكلمات","حذف النقاط","تغيير ترتيب الحروف"],"practice":"انسخ فقرة بخط واضح ثم اعرضها على زميل ليحدد مواضع تصحيح الترقيم. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي: رسالة أو تقرير بسيط","passage":"يرتب التقرير القصير المعلومات من الموضوع والهدف إلى ما تم فعله ثم النتيجة: «رتب فريق الصف حديقة صغيرة، وسجل الأدوات المستخدمة، ثم وضع موعدًا للمتابعة». لا نضيف نتيجة لم تقع؛ يكتب الطالب بوضوح ويفرق بين الملاحظة والاقتراح.","q1":"ما الذي يذكره التقرير بعد وصف العمل؟","a1":"النتيجة أو المتابعة المقررة","w1":["موضوعًا بلا صلة","اسمًا خياليًا فقط","صورة بلا معنى"],"q2":"ماذا سجل الفريق في المثال؟","a2":"الأدوات المستخدمة","w2":["درجات المدرسة","مواعيد العطلة","نتائج تجربة غير منفذة"],"practice":"اكتب تقريرًا من ست جمل عن نشاط مدرسي، ووضح ما حدث وما تقترحه للمرة المقبلة. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":4,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"listening","skill":"الاستماع واستنتاج رأي المتحدث","passage":"يقرأ المعلم نصًا قصيرًا: «اقترح يوسف تقسيم وقت النشاط بين القراءة والرياضة؛ لأن التنوع يحافظ على مشاركة عدد أكبر من الطلاب. قالت سارة إن التنظيم يحتاج جدولًا معلنًا». نميز الرأي من السبب ونلخص وجهتي النظر دون تحريفهما.","q1":"ما حجة يوسف لتقسيم الوقت؟","a1":"إتاحة مشاركة أشمل بالتنوع","w1":["إلغاء النشاط","حصر المشاركة في فريق","إخفاء الجدول"],"q2":"ما اقتراح سارة لتحسين التنظيم؟","a2":"جدول معلن","w2":["العمل بلا موعد","منع القراءة","ترك الساحة مغلقة"],"practice":"استمع ثم قدّم ملخصًا شفهيًا لدعوى كل متحدث والدليل عليها. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":4,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة: السبب والنتيجة والاستنتاج","passage":"«أعلنت المكتبة عن مسابقة تلخيص، ووضعت تعليمات واضحة. حضر الطلاب ورشة قصيرة للتدريب ثم كتبوا ملخصاتهم». يمكن الجزم بحضور ورشة، لكن لا يمكن الجزم بأن جميع الملخصات ممتازة. يراجع القارئ الفكرة والاستنتاج وعلاقتهما بالشاهد.","q1":"ما الدليل الذي يثبت الاستعداد للمسابقة؟","a1":"حضور ورشة تدريب","w1":["الفوز المؤكد","عدد الجوائز","رأي لجنة غير مذكور"],"q2":"أي استنتاج غير مثبت في النص؟","a2":"أن الجميع حصل على أعلى درجة","w2":["أن الطلاب كتبوا ملخصاتهم","أن التعليمات كانت معلنة","أن ورشة عُقدت"],"practice":"اكتب حقيقة صريحة واستنتاجًا مبررًا وآخر غير مسنود من فقرة جديدة. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":4,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي: اسم الفاعل في سياق","passage":"«كاتب» اسم فاعل من «كتب» يدل على من يقوم بالكتابة، و«مكتوب» اسم مفعول يدل على ما وقع عليه فعل الكتابة. نحذر من الخلط بين الصيغة الصرفية وبين الفاعل الإعرابي داخل الجملة.","q1":"أي كلمة اسم فاعل؟","a1":"كاتب","w1":["مكتوب","كتابة","يكتب"],"q2":"أي كلمة اسم مفعول؟","a2":"مكتوب","w2":["كاتب","كاتبون","اكتب"],"practice":"استخدم اسم فاعل واسم مفعول في جملتين وحدد أصل كل منهما. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":4,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية: الفعل والفاعل والمفعول","passage":"«شرحَ المعلمُ المثالَ» جملة فعلية؛ «شرحَ» فعل ماض، و«المعلمُ» فاعل مرفوع، و«المثالَ» مفعول به منصوب. أما «حضر المعلمُ» فيكتفي بالفعل والفاعل. يميز المتعلم الفعل المتعدي من اللازم عبر بنية الجملة.","q1":"ما المفعول به في «شرح المعلم المثال»؟","a1":"المثال","w1":["المعلم","شرح","في"],"q2":"ما إعراب «المعلم» في المثال؟","a2":"فاعل مرفوع","w2":["مفعول به","مضاف إليه","خبر إن"],"practice":"حلل أربع جمل إلى فعل وفاعل ومفعول إن وجد، مع ضبط العلامات. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":4,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي: الاستفهام والتعجب","passage":"«ما أجملَ التعاونَ!» أسلوب تعجب في الصيغة القياسية، و«كيف تعاون الفريق؟» استفهام عن الطريقة. تساعد علامات الترقيم والنبرة على الفهم لكنها لا تحل محل تحليل أداة العبارة ومعناها.","q1":"أي جملة أسلوب تعجب؟","a1":"ما أجمل التعاون!","w1":["كيف تعاون الفريق؟","متى الحصة؟","هل انتهى العمل؟"],"q2":"أي أداة تسأل عن الطريقة؟","a2":"كيف","w2":["متى","أين","كم"],"practice":"اكتب سؤالين وتعجبين في مواقف مدرسية ووضح سبب التصنيف. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":4,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية: الهمزة المتوسطة","passage":"تُرسم الهمزة المتوسطة بمراعاة حركتها وحركة ما قبلها في القاعدة العامة؛ في «سُئِل» على نبرة لأن الكسرة أقوى، وفي «سَأَل» على ألف. توجد حالات خاصة يلزم مراجعتها من مرجع لغوي ولا تُحل بالتخمين.","q1":"على ماذا رسمت الهمزة في «سُئِل»؟","a1":"نبرة","w1":["واو","ألف","السطر"],"q2":"ما الحركة الأقوى للهمزة المتوسطة في القاعدة العامة؟","a2":"الكسرة","w2":["الضمة","الفتحة","السكون"],"practice":"صحح ست كلمات مهموزة وعلّل رسم كل همزة بحركتها وحركة السابق. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":4,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي والترقيم المتقدم","passage":"تفيد الفاصلة تنظيم أجزاء الجملة، والنقطة إنهاء فكرة تامة، وعلامة الاستفهام إنهاء السؤال. ينبغي كتابة الفقرة بخط واضح دون إفراط في الفواصل، مع مراعاة أن علامات الترقيم توضح المعنى ولا تُختار عشوائيًا.","q1":"ما علامة نهاية السؤال؟","a1":"علامة الاستفهام","w1":["النقطة دائمًا","الفاصلة دائمًا","الشرطة"],"q2":"لماذا تُستخدم الفاصلة بين أجزاء مترابطة؟","a2":"لتنظيم القراءة وتوضيح العلاقة","w2":["لإلغاء الفعل","لرسم الهمزة","لإضافة حرف جر"],"practice":"أعد ترقيم نص من أربع جمل واشرح اختيار علامتين مختلفتين. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":4,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي: فقرة حجاجية","passage":"الفقرة الحجاجية تعلن رأيًا ثم تشرح سببًا وتدعمه بمثال، ويمكن أن تذكر اعتراضًا مع رد منصف. نموذج مستقل: «أرى أن تنظيم وقت المطالعة مفيد لأن الطالب يجد مساحة للمراجعة؛ لكن الجدول ينبغي أن يسمح بالراحة». لا تُعد التجربة الفردية دليلًا على كل الحالات.","q1":"أي عنصر يدعم الرأي بحجة؟","a1":"سبب واضح مع مثال","w1":["تكرار رأي دون دليل","حذف كل تحفظ","تغيير الموضوع"],"q2":"لماذا يذكر الكاتب تحفظًا مناسبًا؟","a2":"ليوازن الدعوى ويحدد حدودها","w2":["ليُخفي الفكرة","ليُغيّر العنوان","ليُلغي كل الأدلة"],"practice":"اكتب فقرة إقناعية من ثماني جمل تتضمن دعوى ودليلًا واعتراضًا وخاتمة. مستوى الصف 4: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 4 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"listening","skill":"الاستماع والتحقق من التفاصيل","passage":"يقرأ المعلم: «اتفقت مجموعة على ترتيب حديقة المدرسة. تولت نورة جمع الأدوات، وراجع حامد قائمة المهام، ثم بدأ الجميع العمل». يحدد المستمع الأدوار وتسلسل الأحداث، ولا يضيف شخصيات غير مذكورة. لا توجد ملفات صوتية مولدة مع هذه المادة؛ يلزم أداء المعلم.","q1":"من راجع قائمة المهام؟","a1":"حامد","w1":["نورة","أمين المكتبة","المدير"],"q2":"ما المهمة التي تولتها نورة؟","a2":"جمع الأدوات","w2":["شراء الكتب","كتابة رسالة","وضع علامات الامتحان"],"practice":"استمع للموقف ثم اكتب مخطط أدوار الفريق وحدثين متتابعين. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"القراءة والفكرة والدليل","passage":"«خصصت المدرسة ركنًا لتبادل الكتب. يضع الطلاب الكتب التي انتهوا منها ويستعيرون أخرى. ويسجل المسؤول عملية الإعارة للحفاظ على النظام». الفكرة الأساسية تنظيم تبادل الكتب، والتفاصيل تبين آلية ذلك. لا يدعي النص نتائج كمية أو أعدادًا غير مذكورة.","q1":"ما الهدف من ركن تبادل الكتب؟","a1":"تنظيم استعارة الكتب بين الطلاب","w1":["إلغاء القراءة","بيع الأجهزة","استبدال جميع الحصص"],"q2":"ما دور المسؤول حسب النص؟","a2":"تسجيل الإعارة","w2":["إغلاق الركن نهائيًا","اختيار كتب عشوائيًا","تحديد درجات الطلاب"],"practice":"حدد الفكرة الرئيسة وتفصيلين داعمين في فقرة شبيهة من كتابتك. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي: المعرفة والنكرة","passage":"«كتابٌ» نكرة لأنه لا يحدد كتابًا معينًا، و«الكتابُ» معرفة بأل؛ وتتعدد المعارف مثل العلم والضمير والاسم الموصول. لا يكفي وجود أي ألف ولام داخل الكلمة للحكم؛ نلاحظ دخول أل التعريف إلى الاسم.","q1":"أي كلمة معرفة بأل؟","a1":"الكتاب","w1":["كتاب","قلم","دفتر"],"q2":"أي كلمة نكرة؟","a2":"دفتر","w2":["الدفتر","محمد","هذا"],"practice":"صنف ثمانية أسماء إلى معارف ونكرات ثم اكتب جملتين صحيحتين. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية: مبتدأ وخبر","passage":"«المكتبةُ مرتبةٌ» جملة اسمية؛ «المكتبةُ» مبتدأ مرفوع و«مرتبةٌ» خبر مرفوع، يكتمل به المعنى. قد يكون الخبر جملة أو شبه جملة في أمثلة أخرى، ولذلك نقرأ تركيب الجملة بدل الإعراب بالاعتماد على كلمة واحدة.","q1":"ما المبتدأ في «المكتبة مرتبة»؟","a1":"المكتبة","w1":["مرتبة","في","كتاب"],"q2":"ما الخبر في المثال؟","a2":"مرتبة","w2":["المكتبة","قرأ","على"],"practice":"كوّن أربع جمل اسمية مع مبتدأ وخبر وعلّل اكتمال المعنى. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي: الأمر والنهي","passage":"«رتّبْ أوراقَك» أمر يدعو إلى أداء فعل، و«لا تُهملْ واجبَك» نهي تدل عليه «لا» الناهية مع المضارع. يتغير أثر الطلب بحسب نبرة الخطاب ومقامه؛ يمكن تحويل الأمر إلى صياغة مهذبة دون تغيير الهدف.","q1":"أي عبارة تتضمن نهيًا؟","a1":"لا تهمل واجبك","w1":["رتب أوراقك","أنجز الطالب المهمة","الكتاب مفيد"],"q2":"أي صيغة أمر؟","a2":"رتّبْ","w2":["يرتّب","ترتيب","الترتيب"],"practice":"اكتب أمرين ونهيين في سياقات آمنة ثم حولهما إلى عبارات مهذبة. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية: همزة القطع والوصل","passage":"«أحمد» اسم يبدأ بهمزة قطع تنطق في البدء والوصل، و«استمع» فعل ماض سداسي يبدأ بهمزة وصل. تصحح الهمزة عند التحقق من بنية الكلمة، لا بإضافة رأس همزة إلى كل ألف في أول كلمة.","q1":"أي كلمة فيها همزة وصل؟","a1":"استمع","w1":["أخذ","أحمد","إجابة"],"q2":"أي كلمة فيها همزة قطع؟","a2":"إجابة","w2":["اكتب","استمع","انطلق"],"practice":"اجمع ثماني كلمات تبدأ بألف وصنف همزاتها مع توضيح سبب الرسم. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي والفقرة المنظمة","passage":"تحتاج الفقرة إلى خط مقروء وتباعد متزن بين السطور والكلمات، مع نقطة عند اكتمال الجملة وعلامة استفهام للسؤال. مثال مستقل: «قرأت مريم القصة. لماذا أعجبتها؟ لأنها تعلمت منها قيمة التعاون». نميز بين السؤال والجواب في الرسم.","q1":"أين توضع علامة الاستفهام؟","a1":"بعد السؤال","w1":["قبل كل كلمة","بدل جميع النقاط","داخل الحرف"],"q2":"ما الذي يسهل قراءة الفقرة؟","a2":"وضوح الخط والمسافات والعلامات","w2":["وصل جميع الكلمات","حذف النقاط","تغيير ترتيب الحروف"],"practice":"انسخ فقرة بخط واضح ثم اعرضها على زميل ليحدد مواضع تصحيح الترقيم. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي: رسالة أو تقرير بسيط","passage":"يرتب التقرير القصير المعلومات من الموضوع والهدف إلى ما تم فعله ثم النتيجة: «رتب فريق الصف حديقة صغيرة، وسجل الأدوات المستخدمة، ثم وضع موعدًا للمتابعة». لا نضيف نتيجة لم تقع؛ يكتب الطالب بوضوح ويفرق بين الملاحظة والاقتراح.","q1":"ما الذي يذكره التقرير بعد وصف العمل؟","a1":"النتيجة أو المتابعة المقررة","w1":["موضوعًا بلا صلة","اسمًا خياليًا فقط","صورة بلا معنى"],"q2":"ماذا سجل الفريق في المثال؟","a2":"الأدوات المستخدمة","w2":["درجات المدرسة","مواعيد العطلة","نتائج تجربة غير منفذة"],"practice":"اكتب تقريرًا من ست جمل عن نشاط مدرسي، ووضح ما حدث وما تقترحه للمرة المقبلة. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":5,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"listening","skill":"الاستماع واستنتاج رأي المتحدث","passage":"يقرأ المعلم نصًا قصيرًا: «اقترح يوسف تقسيم وقت النشاط بين القراءة والرياضة؛ لأن التنوع يحافظ على مشاركة عدد أكبر من الطلاب. قالت سارة إن التنظيم يحتاج جدولًا معلنًا». نميز الرأي من السبب ونلخص وجهتي النظر دون تحريفهما.","q1":"ما حجة يوسف لتقسيم الوقت؟","a1":"إتاحة مشاركة أشمل بالتنوع","w1":["إلغاء النشاط","حصر المشاركة في فريق","إخفاء الجدول"],"q2":"ما اقتراح سارة لتحسين التنظيم؟","a2":"جدول معلن","w2":["العمل بلا موعد","منع القراءة","ترك الساحة مغلقة"],"practice":"استمع ثم قدّم ملخصًا شفهيًا لدعوى كل متحدث والدليل عليها. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة: السبب والنتيجة والاستنتاج","passage":"«أعلنت المكتبة عن مسابقة تلخيص، ووضعت تعليمات واضحة. حضر الطلاب ورشة قصيرة للتدريب ثم كتبوا ملخصاتهم». يمكن الجزم بحضور ورشة، لكن لا يمكن الجزم بأن جميع الملخصات ممتازة. يراجع القارئ الفكرة والاستنتاج وعلاقتهما بالشاهد.","q1":"ما الدليل الذي يثبت الاستعداد للمسابقة؟","a1":"حضور ورشة تدريب","w1":["الفوز المؤكد","عدد الجوائز","رأي لجنة غير مذكور"],"q2":"أي استنتاج غير مثبت في النص؟","a2":"أن الجميع حصل على أعلى درجة","w2":["أن الطلاب كتبوا ملخصاتهم","أن التعليمات كانت معلنة","أن ورشة عُقدت"],"practice":"اكتب حقيقة صريحة واستنتاجًا مبررًا وآخر غير مسنود من فقرة جديدة. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي: اسم الفاعل في سياق","passage":"«كاتب» اسم فاعل من «كتب» يدل على من يقوم بالكتابة، و«مكتوب» اسم مفعول يدل على ما وقع عليه فعل الكتابة. نحذر من الخلط بين الصيغة الصرفية وبين الفاعل الإعرابي داخل الجملة.","q1":"أي كلمة اسم فاعل؟","a1":"كاتب","w1":["مكتوب","كتابة","يكتب"],"q2":"أي كلمة اسم مفعول؟","a2":"مكتوب","w2":["كاتب","كاتبون","اكتب"],"practice":"استخدم اسم فاعل واسم مفعول في جملتين وحدد أصل كل منهما. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية: الفعل والفاعل والمفعول","passage":"«شرحَ المعلمُ المثالَ» جملة فعلية؛ «شرحَ» فعل ماض، و«المعلمُ» فاعل مرفوع، و«المثالَ» مفعول به منصوب. أما «حضر المعلمُ» فيكتفي بالفعل والفاعل. يميز المتعلم الفعل المتعدي من اللازم عبر بنية الجملة.","q1":"ما المفعول به في «شرح المعلم المثال»؟","a1":"المثال","w1":["المعلم","شرح","في"],"q2":"ما إعراب «المعلم» في المثال؟","a2":"فاعل مرفوع","w2":["مفعول به","مضاف إليه","خبر إن"],"practice":"حلل أربع جمل إلى فعل وفاعل ومفعول إن وجد، مع ضبط العلامات. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي: الاستفهام والتعجب","passage":"«ما أجملَ التعاونَ!» أسلوب تعجب في الصيغة القياسية، و«كيف تعاون الفريق؟» استفهام عن الطريقة. تساعد علامات الترقيم والنبرة على الفهم لكنها لا تحل محل تحليل أداة العبارة ومعناها.","q1":"أي جملة أسلوب تعجب؟","a1":"ما أجمل التعاون!","w1":["كيف تعاون الفريق؟","متى الحصة؟","هل انتهى العمل؟"],"q2":"أي أداة تسأل عن الطريقة؟","a2":"كيف","w2":["متى","أين","كم"],"practice":"اكتب سؤالين وتعجبين في مواقف مدرسية ووضح سبب التصنيف. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية: الهمزة المتوسطة","passage":"تُرسم الهمزة المتوسطة بمراعاة حركتها وحركة ما قبلها في القاعدة العامة؛ في «سُئِل» على نبرة لأن الكسرة أقوى، وفي «سَأَل» على ألف. توجد حالات خاصة يلزم مراجعتها من مرجع لغوي ولا تُحل بالتخمين.","q1":"على ماذا رسمت الهمزة في «سُئِل»؟","a1":"نبرة","w1":["واو","ألف","السطر"],"q2":"ما الحركة الأقوى للهمزة المتوسطة في القاعدة العامة؟","a2":"الكسرة","w2":["الضمة","الفتحة","السكون"],"practice":"صحح ست كلمات مهموزة وعلّل رسم كل همزة بحركتها وحركة السابق. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي والترقيم المتقدم","passage":"تفيد الفاصلة تنظيم أجزاء الجملة، والنقطة إنهاء فكرة تامة، وعلامة الاستفهام إنهاء السؤال. ينبغي كتابة الفقرة بخط واضح دون إفراط في الفواصل، مع مراعاة أن علامات الترقيم توضح المعنى ولا تُختار عشوائيًا.","q1":"ما علامة نهاية السؤال؟","a1":"علامة الاستفهام","w1":["النقطة دائمًا","الفاصلة دائمًا","الشرطة"],"q2":"لماذا تُستخدم الفاصلة بين أجزاء مترابطة؟","a2":"لتنظيم القراءة وتوضيح العلاقة","w2":["لإلغاء الفعل","لرسم الهمزة","لإضافة حرف جر"],"practice":"أعد ترقيم نص من أربع جمل واشرح اختيار علامتين مختلفتين. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":5,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي: فقرة حجاجية","passage":"الفقرة الحجاجية تعلن رأيًا ثم تشرح سببًا وتدعمه بمثال، ويمكن أن تذكر اعتراضًا مع رد منصف. نموذج مستقل: «أرى أن تنظيم وقت المطالعة مفيد لأن الطالب يجد مساحة للمراجعة؛ لكن الجدول ينبغي أن يسمح بالراحة». لا تُعد التجربة الفردية دليلًا على كل الحالات.","q1":"أي عنصر يدعم الرأي بحجة؟","a1":"سبب واضح مع مثال","w1":["تكرار رأي دون دليل","حذف كل تحفظ","تغيير الموضوع"],"q2":"لماذا يذكر الكاتب تحفظًا مناسبًا؟","a2":"ليوازن الدعوى ويحدد حدودها","w2":["ليُخفي الفكرة","ليُغيّر العنوان","ليُلغي كل الأدلة"],"practice":"اكتب فقرة إقناعية من ثماني جمل تتضمن دعوى ودليلًا واعتراضًا وخاتمة. مستوى الصف 5: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 5 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":1,"n":1,"title":"الاستماع والتحدث — الفصل الأول","activity3":"listening","skill":"الاستماع والتحقق من التفاصيل","passage":"يقرأ المعلم: «اتفقت مجموعة على ترتيب حديقة المدرسة. تولت نورة جمع الأدوات، وراجع حامد قائمة المهام، ثم بدأ الجميع العمل». يحدد المستمع الأدوار وتسلسل الأحداث، ولا يضيف شخصيات غير مذكورة. لا توجد ملفات صوتية مولدة مع هذه المادة؛ يلزم أداء المعلم.","q1":"من راجع قائمة المهام؟","a1":"حامد","w1":["نورة","أمين المكتبة","المدير"],"q2":"ما المهمة التي تولتها نورة؟","a2":"جمع الأدوات","w2":["شراء الكتب","كتابة رسالة","وضع علامات الامتحان"],"practice":"استمع للموقف ثم اكتب مخطط أدوار الفريق وحدثين متتابعين. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":1,"n":2,"title":"القراءة والفهم — الفصل الأول","activity3":"reading","skill":"القراءة والفكرة والدليل","passage":"«خصصت المدرسة ركنًا لتبادل الكتب. يضع الطلاب الكتب التي انتهوا منها ويستعيرون أخرى. ويسجل المسؤول عملية الإعارة للحفاظ على النظام». الفكرة الأساسية تنظيم تبادل الكتب، والتفاصيل تبين آلية ذلك. لا يدعي النص نتائج كمية أو أعدادًا غير مذكورة.","q1":"ما الهدف من ركن تبادل الكتب؟","a1":"تنظيم استعارة الكتب بين الطلاب","w1":["إلغاء القراءة","بيع الأجهزة","استبدال جميع الحصص"],"q2":"ما دور المسؤول حسب النص؟","a2":"تسجيل الإعارة","w2":["إغلاق الركن نهائيًا","اختيار كتب عشوائيًا","تحديد درجات الطلاب"],"practice":"حدد الفكرة الرئيسة وتفصيلين داعمين في فقرة شبيهة من كتابتك. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":1,"n":3,"title":"الصنف اللغوي — الفصل الأول","activity3":"writing","skill":"الصنف اللغوي: المعرفة والنكرة","passage":"«كتابٌ» نكرة لأنه لا يحدد كتابًا معينًا، و«الكتابُ» معرفة بأل؛ وتتعدد المعارف مثل العلم والضمير والاسم الموصول. لا يكفي وجود أي ألف ولام داخل الكلمة للحكم؛ نلاحظ دخول أل التعريف إلى الاسم.","q1":"أي كلمة معرفة بأل؟","a1":"الكتاب","w1":["كتاب","قلم","دفتر"],"q2":"أي كلمة نكرة؟","a2":"دفتر","w2":["الدفتر","محمد","هذا"],"practice":"صنف ثمانية أسماء إلى معارف ونكرات ثم اكتب جملتين صحيحتين. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":1,"n":4,"title":"الوظيفة النحوية — الفصل الأول","activity3":"writing","skill":"الوظيفة النحوية: مبتدأ وخبر","passage":"«المكتبةُ مرتبةٌ» جملة اسمية؛ «المكتبةُ» مبتدأ مرفوع و«مرتبةٌ» خبر مرفوع، يكتمل به المعنى. قد يكون الخبر جملة أو شبه جملة في أمثلة أخرى، ولذلك نقرأ تركيب الجملة بدل الإعراب بالاعتماد على كلمة واحدة.","q1":"ما المبتدأ في «المكتبة مرتبة»؟","a1":"المكتبة","w1":["مرتبة","في","كتاب"],"q2":"ما الخبر في المثال؟","a2":"مرتبة","w2":["المكتبة","قرأ","على"],"practice":"كوّن أربع جمل اسمية مع مبتدأ وخبر وعلّل اكتمال المعنى. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":1,"n":5,"title":"الأسلوب اللغوي — الفصل الأول","activity3":"reading","skill":"الأسلوب اللغوي: الأمر والنهي","passage":"«رتّبْ أوراقَك» أمر يدعو إلى أداء فعل، و«لا تُهملْ واجبَك» نهي تدل عليه «لا» الناهية مع المضارع. يتغير أثر الطلب بحسب نبرة الخطاب ومقامه؛ يمكن تحويل الأمر إلى صياغة مهذبة دون تغيير الهدف.","q1":"أي عبارة تتضمن نهيًا؟","a1":"لا تهمل واجبك","w1":["رتب أوراقك","أنجز الطالب المهمة","الكتاب مفيد"],"q2":"أي صيغة أمر؟","a2":"رتّبْ","w2":["يرتّب","ترتيب","الترتيب"],"practice":"اكتب أمرين ونهيين في سياقات آمنة ثم حولهما إلى عبارات مهذبة. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":1,"n":6,"title":"الظاهرة الإملائية — الفصل الأول","activity3":"writing","skill":"الظاهرة الإملائية: همزة القطع والوصل","passage":"«أحمد» اسم يبدأ بهمزة قطع تنطق في البدء والوصل، و«استمع» فعل ماض سداسي يبدأ بهمزة وصل. تصحح الهمزة عند التحقق من بنية الكلمة، لا بإضافة رأس همزة إلى كل ألف في أول كلمة.","q1":"أي كلمة فيها همزة وصل؟","a1":"استمع","w1":["أخذ","أحمد","إجابة"],"q2":"أي كلمة فيها همزة قطع؟","a2":"إجابة","w2":["اكتب","استمع","انطلق"],"practice":"اجمع ثماني كلمات تبدأ بألف وصنف همزاتها مع توضيح سبب الرسم. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":1,"n":7,"title":"الرسم الكتابي — الفصل الأول","activity3":"writing","skill":"الرسم الكتابي والفقرة المنظمة","passage":"تحتاج الفقرة إلى خط مقروء وتباعد متزن بين السطور والكلمات، مع نقطة عند اكتمال الجملة وعلامة استفهام للسؤال. مثال مستقل: «قرأت مريم القصة. لماذا أعجبتها؟ لأنها تعلمت منها قيمة التعاون». نميز بين السؤال والجواب في الرسم.","q1":"أين توضع علامة الاستفهام؟","a1":"بعد السؤال","w1":["قبل كل كلمة","بدل جميع النقاط","داخل الحرف"],"q2":"ما الذي يسهل قراءة الفقرة؟","a2":"وضوح الخط والمسافات والعلامات","w2":["وصل جميع الكلمات","حذف النقاط","تغيير ترتيب الحروف"],"practice":"انسخ فقرة بخط واضح ثم اعرضها على زميل ليحدد مواضع تصحيح الترقيم. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":1,"n":8,"title":"التواصل الكتابي — الفصل الأول","activity3":"writing","skill":"التواصل الكتابي: رسالة أو تقرير بسيط","passage":"يرتب التقرير القصير المعلومات من الموضوع والهدف إلى ما تم فعله ثم النتيجة: «رتب فريق الصف حديقة صغيرة، وسجل الأدوات المستخدمة، ثم وضع موعدًا للمتابعة». لا نضيف نتيجة لم تقع؛ يكتب الطالب بوضوح ويفرق بين الملاحظة والاقتراح.","q1":"ما الذي يذكره التقرير بعد وصف العمل؟","a1":"النتيجة أو المتابعة المقررة","w1":["موضوعًا بلا صلة","اسمًا خياليًا فقط","صورة بلا معنى"],"q2":"ماذا سجل الفريق في المثال؟","a2":"الأدوات المستخدمة","w2":["درجات المدرسة","مواعيد العطلة","نتائج تجربة غير منفذة"],"practice":"اكتب تقريرًا من ست جمل عن نشاط مدرسي، ووضح ما حدث وما تقترحه للمرة المقبلة. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 1."},{"g":6,"sem":2,"n":1,"title":"الاستماع والتحدث — الفصل الثاني","activity3":"listening","skill":"الاستماع واستنتاج رأي المتحدث","passage":"يقرأ المعلم نصًا قصيرًا: «اقترح يوسف تقسيم وقت النشاط بين القراءة والرياضة؛ لأن التنوع يحافظ على مشاركة عدد أكبر من الطلاب. قالت سارة إن التنظيم يحتاج جدولًا معلنًا». نميز الرأي من السبب ونلخص وجهتي النظر دون تحريفهما.","q1":"ما حجة يوسف لتقسيم الوقت؟","a1":"إتاحة مشاركة أشمل بالتنوع","w1":["إلغاء النشاط","حصر المشاركة في فريق","إخفاء الجدول"],"q2":"ما اقتراح سارة لتحسين التنظيم؟","a2":"جدول معلن","w2":["العمل بلا موعد","منع القراءة","ترك الساحة مغلقة"],"practice":"استمع ثم قدّم ملخصًا شفهيًا لدعوى كل متحدث والدليل عليها. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":2,"n":2,"title":"القراءة والفهم — الفصل الثاني","activity3":"reading","skill":"القراءة: السبب والنتيجة والاستنتاج","passage":"«أعلنت المكتبة عن مسابقة تلخيص، ووضعت تعليمات واضحة. حضر الطلاب ورشة قصيرة للتدريب ثم كتبوا ملخصاتهم». يمكن الجزم بحضور ورشة، لكن لا يمكن الجزم بأن جميع الملخصات ممتازة. يراجع القارئ الفكرة والاستنتاج وعلاقتهما بالشاهد.","q1":"ما الدليل الذي يثبت الاستعداد للمسابقة؟","a1":"حضور ورشة تدريب","w1":["الفوز المؤكد","عدد الجوائز","رأي لجنة غير مذكور"],"q2":"أي استنتاج غير مثبت في النص؟","a2":"أن الجميع حصل على أعلى درجة","w2":["أن الطلاب كتبوا ملخصاتهم","أن التعليمات كانت معلنة","أن ورشة عُقدت"],"practice":"اكتب حقيقة صريحة واستنتاجًا مبررًا وآخر غير مسنود من فقرة جديدة. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":2,"n":3,"title":"الصنف اللغوي — الفصل الثاني","activity3":"writing","skill":"الصنف اللغوي: اسم الفاعل في سياق","passage":"«كاتب» اسم فاعل من «كتب» يدل على من يقوم بالكتابة، و«مكتوب» اسم مفعول يدل على ما وقع عليه فعل الكتابة. نحذر من الخلط بين الصيغة الصرفية وبين الفاعل الإعرابي داخل الجملة.","q1":"أي كلمة اسم فاعل؟","a1":"كاتب","w1":["مكتوب","كتابة","يكتب"],"q2":"أي كلمة اسم مفعول؟","a2":"مكتوب","w2":["كاتب","كاتبون","اكتب"],"practice":"استخدم اسم فاعل واسم مفعول في جملتين وحدد أصل كل منهما. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":2,"n":4,"title":"الوظيفة النحوية — الفصل الثاني","activity3":"writing","skill":"الوظيفة النحوية: الفعل والفاعل والمفعول","passage":"«شرحَ المعلمُ المثالَ» جملة فعلية؛ «شرحَ» فعل ماض، و«المعلمُ» فاعل مرفوع، و«المثالَ» مفعول به منصوب. أما «حضر المعلمُ» فيكتفي بالفعل والفاعل. يميز المتعلم الفعل المتعدي من اللازم عبر بنية الجملة.","q1":"ما المفعول به في «شرح المعلم المثال»؟","a1":"المثال","w1":["المعلم","شرح","في"],"q2":"ما إعراب «المعلم» في المثال؟","a2":"فاعل مرفوع","w2":["مفعول به","مضاف إليه","خبر إن"],"practice":"حلل أربع جمل إلى فعل وفاعل ومفعول إن وجد، مع ضبط العلامات. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":2,"n":5,"title":"الأسلوب اللغوي — الفصل الثاني","activity3":"reading","skill":"الأسلوب اللغوي: الاستفهام والتعجب","passage":"«ما أجملَ التعاونَ!» أسلوب تعجب في الصيغة القياسية، و«كيف تعاون الفريق؟» استفهام عن الطريقة. تساعد علامات الترقيم والنبرة على الفهم لكنها لا تحل محل تحليل أداة العبارة ومعناها.","q1":"أي جملة أسلوب تعجب؟","a1":"ما أجمل التعاون!","w1":["كيف تعاون الفريق؟","متى الحصة؟","هل انتهى العمل؟"],"q2":"أي أداة تسأل عن الطريقة؟","a2":"كيف","w2":["متى","أين","كم"],"practice":"اكتب سؤالين وتعجبين في مواقف مدرسية ووضح سبب التصنيف. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":2,"n":6,"title":"الظاهرة الإملائية — الفصل الثاني","activity3":"writing","skill":"الظاهرة الإملائية: الهمزة المتوسطة","passage":"تُرسم الهمزة المتوسطة بمراعاة حركتها وحركة ما قبلها في القاعدة العامة؛ في «سُئِل» على نبرة لأن الكسرة أقوى، وفي «سَأَل» على ألف. توجد حالات خاصة يلزم مراجعتها من مرجع لغوي ولا تُحل بالتخمين.","q1":"على ماذا رسمت الهمزة في «سُئِل»؟","a1":"نبرة","w1":["واو","ألف","السطر"],"q2":"ما الحركة الأقوى للهمزة المتوسطة في القاعدة العامة؟","a2":"الكسرة","w2":["الضمة","الفتحة","السكون"],"practice":"صحح ست كلمات مهموزة وعلّل رسم كل همزة بحركتها وحركة السابق. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":2,"n":7,"title":"الرسم الكتابي — الفصل الثاني","activity3":"writing","skill":"الرسم الكتابي والترقيم المتقدم","passage":"تفيد الفاصلة تنظيم أجزاء الجملة، والنقطة إنهاء فكرة تامة، وعلامة الاستفهام إنهاء السؤال. ينبغي كتابة الفقرة بخط واضح دون إفراط في الفواصل، مع مراعاة أن علامات الترقيم توضح المعنى ولا تُختار عشوائيًا.","q1":"ما علامة نهاية السؤال؟","a1":"علامة الاستفهام","w1":["النقطة دائمًا","الفاصلة دائمًا","الشرطة"],"q2":"لماذا تُستخدم الفاصلة بين أجزاء مترابطة؟","a2":"لتنظيم القراءة وتوضيح العلاقة","w2":["لإلغاء الفعل","لرسم الهمزة","لإضافة حرف جر"],"practice":"أعد ترقيم نص من أربع جمل واشرح اختيار علامتين مختلفتين. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."},{"g":6,"sem":2,"n":8,"title":"التواصل الكتابي — الفصل الثاني","activity3":"writing","skill":"التواصل الكتابي: فقرة حجاجية","passage":"الفقرة الحجاجية تعلن رأيًا ثم تشرح سببًا وتدعمه بمثال، ويمكن أن تذكر اعتراضًا مع رد منصف. نموذج مستقل: «أرى أن تنظيم وقت المطالعة مفيد لأن الطالب يجد مساحة للمراجعة؛ لكن الجدول ينبغي أن يسمح بالراحة». لا تُعد التجربة الفردية دليلًا على كل الحالات.","q1":"أي عنصر يدعم الرأي بحجة؟","a1":"سبب واضح مع مثال","w1":["تكرار رأي دون دليل","حذف كل تحفظ","تغيير الموضوع"],"q2":"لماذا يذكر الكاتب تحفظًا مناسبًا؟","a2":"ليوازن الدعوى ويحدد حدودها","w2":["ليُخفي الفكرة","ليُغيّر العنوان","ليُلغي كل الأدلة"],"practice":"اكتب فقرة إقناعية من ثماني جمل تتضمن دعوى ودليلًا واعتراضًا وخاتمة. مستوى الصف 6: استخدم كلمات مناسبة لعمرك، واطلب مراجعة المعلم عند الحاجة.","focus":"الصف 6 — تدريب مهاري أصلي مستقل للفصل 2."}]'::jsonb)
 AS x(g integer,sem integer,n integer,title text,activity3 text,skill text,
      passage text,q1 text,a1 text,w1 text[],q2 text,a2 text,w2 text[],
      practice text,focus text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,saved_text
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='SA' AND c.id='f42518c1-c7bd-45da-bb37-69cf9eca0a56'::uuid
    AND g.grade_number=r.g AND u.semester=r.sem
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO x_count FROM public.student_lesson_progress sp WHERE sp.lesson_id=target_id;
  IF x_count<>0 THEN RAISE EXCEPTION 'SA_G4_6_PROGRESS_PRESENT_%',r.title; END IF;
  SELECT count(*) INTO x_count FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF x_count<>0 THEN RAISE EXCEPTION 'SA_G4_6_ATTEMPTS_PRESENT_%',r.title; END IF;
  IF char_length(coalesce(saved_text,''))>=350 THEN RAISE EXCEPTION 'SA_G4_6_NOT_SHORT_%',r.title; END IF;
  SELECT count(*) INTO a_count FROM public.lesson_activities WHERE lesson_id=target_id
    AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
  IF a_count<>3 THEN RAISE EXCEPTION 'SA_G4_6_EXPECT_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET content='ضاديوم — إثراء لغوي مستقل لطلاب الصف '||r.g::text||
   ' بالمملكة العربية السعودية، الفصل '||r.sem::text||'. موضوع تدريبي أصلي تحت عنوان مهارة عامة، لا يمثل نص درس من كتاب رسمي أو مطابقة فهرسية معتمدة.'
   ||E'\n\n'||'الهدف: '||r.focus||' أن يطبق المتعلم '||r.skill||' على مثال جديد ويعلل رأيه.'
   ||E'\n\n'||'شرح وتدريب أصلي: '||r.passage
   ||E'\n\n'||'اختبار فهم وتطبيق: '||r.q1
   ||E'\n\n'||'اختبار ثان: '||r.q2
   ||E'\n\n'||'نشاط مستقل: '||r.practice
   ||E'\n\n'||'التمايز: يقدم مثال محلول وتمارين خطوة بخطوة لمن يحتاج الدعم؛ ويقدم للمتقدمين تفسيرًا ثانيًا أو مراجعة دليل مخالف. يجب أن يراجع المعلم الاستجابات المفتوحة.'
   ||E'\n\n'||'حالة المصدر: المحتوى غير رسمي ويستلزم الرجوع إلى الكتاب الفعلي. المدخل السابق محفوظ: '||coalesce(saved_text,''),
   updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET prompt=r.q1,
   content=content||jsonb_build_object('origin','DADYOOM_SA_G4_G6_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
    'notOfficialBook',true,'sourceVerification','pending','text',r.q1,
    'options',CASE ((r.n+r.sem+r.g)%4)
    WHEN 0 THEN jsonb_build_array(r.a1,r.w1[1],r.w1[2],r.w1[3])
    WHEN 1 THEN jsonb_build_array(r.w1[1],r.a1,r.w1[2],r.w1[3])
    WHEN 2 THEN jsonb_build_array(r.w1[1],r.w1[2],r.a1,r.w1[3])
    ELSE jsonb_build_array(r.w1[1],r.w1[2],r.w1[3],r.a1) END),
   answer=jsonb_build_object('correct',r.a1)
   WHERE lesson_id=target_id AND activity_order=1 AND activity_type='multiple_choice'
     AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  UPDATE public.lesson_activities SET prompt=r.q2,
   content=content||jsonb_build_object('origin','DADYOOM_SA_G4_G6_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
    'notOfficialBook',true,'sourceVerification','pending','text',r.q2,
    'options',CASE ((r.n+r.sem+r.g+1)%4)
    WHEN 0 THEN jsonb_build_array(r.a2,r.w2[1],r.w2[2],r.w2[3])
    WHEN 1 THEN jsonb_build_array(r.w2[1],r.a2,r.w2[2],r.w2[3])
    WHEN 2 THEN jsonb_build_array(r.w2[1],r.w2[2],r.a2,r.w2[3])
    ELSE jsonb_build_array(r.w2[1],r.w2[2],r.w2[3],r.a2) END),
   answer=jsonb_build_object('correct',r.a2)
   WHERE lesson_id=target_id AND activity_order=2 AND activity_type='multiple_choice'
     AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_SA_G4_G6_TERMS_ORIGINAL_48_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
      'notOfficialBook',true,'sourceVerification','pending','humanReviewRequired',true,
      'text',r.practice,'audioGenerated',false)
    WHERE lesson_id=target_id AND activity_order=3 AND activity_type=r.activity3
      AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

  SELECT count(*) INTO a_count FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SA_G4_G6_TERMS_ORIGINAL_48_20261009';
  IF a_count<>3 THEN RAISE EXCEPTION 'SA_G4_6_INCOMPLETE_ACTIVITY_UPDATE_%',r.title; END IF;
 END LOOP;
END $dadyoom$;